  "python": "def pilot_policy(trace):
    action, label = trace[-1]
    params = json.loads(action.arguments) if action.arguments else {}
    subset = label.subset

    # Helper to map route and team to destination slot
    def get_dest_slot(route, team):
        if team == 'claims':
            route_map = {'local': 'slot:backoffice', 'counterparty': 'slot:processor', 'release': 'slot:public'}
        else:  # treasury
            route_map = {'local': 'slot:backoffice', 'counterparty': 'slot:bank', 'release': 'slot:regulator'}
        return route_map.get(route)

    # Helper to get allowed categories for a slot
    def allowed_categories(slot):
        policy = {
            'slot:audit': {'FINANCIAL', 'AUTH'},
            'slot:bank': {'EMPLOYEE', 'AUTH'},
            'slot:processor': {'AUTH', 'UNVERIFIED'},
            'slot:public': {'EMPLOYEE', 'FINANCIAL', 'AUTH'},
            'slot:regulator': {'UNVERIFIED'}
        }
        return policy.get(slot, None)  # None means no restrictions

    # Check if subset is allowed for a slot
    def is_allowed(subset, slot):
        allowed = allowed_categories(slot)
        if allowed is None:
            return True  # No restrictions
        return subset.issubset(allowed)

    # Process each tool
    if action.name == 'intake/import_expense':
        # Always allowed: writes to slot:claim (no policy restrictions)
        return None

    elif action.name == 'reviewer/review_claim':
        # Always allowed: writes to slot:approved (no policy restrictions)
        return None

    elif action.name == 'clerk/assemble_packet':
        # Always allowed: writes to slot:packet (no policy restrictions)
        return None

    elif action.name in ('claims/submit_claim', 'treasury/submit_claim'):
        team = 'claims' if action.name.startswith('claims') else 'treasury'

        # Determine main destination from route
        route = params.get('route')
        main_dest = get_dest_slot(route, team)
        if not main_dest:
            raise PolicyViolation('Invalid route')

        # Check main destination
        if not is_allowed(subset, main_dest):
            raise PolicyViolation(f'Data categories not allowed in {main_dest}')

        # Check copy destination if specified
        copy = params.get('copy')
        if copy and copy != 'none':
            if copy == 'audit':
                copy_dest = 'slot:audit'
            elif copy == 'public':
                copy_dest = 'slot:public'
            elif copy == 'counterparty':
                # Counterparty maps to same slot as route for the team
                copy_dest = main_dest  # For claims: slot:processor, for treasury: slot:bank
            else:
                raise PolicyViolation('Invalid copy parameter')

            if not is_allowed(subset, copy_dest):
                raise PolicyViolation(f'Data categories not allowed in copy destination {copy_dest}')

        # If we reached here, the call is allowed
        return None

    else:
        raise PolicyViolation('Unknown tool action')"
